import org.apache.flink.streaming.api.functions.source.SourceFunction;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.zip.GZIPInputStream;

public class TaskEventSource implements SourceFunction<TaskEvent> {

    private final String path;
    private volatile boolean running = true;

    public TaskEventSource(String path) {
        this.path = path;
    }

    @Override
    public void run(SourceContext<TaskEvent> ctx) throws Exception {
        try (InputStream raw = Files.newInputStream(Path.of(path));
             InputStream in = path.endsWith(".gz") ? new GZIPInputStream(raw) : raw;
             BufferedReader br = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8))) {

            String line;
            while (running && (line = br.readLine()) != null) {
                line = line.trim();
                if (line.isEmpty()) {
                    continue;
                }

                String[] f = line.split(",", -1);
                if (f.length < 6) {
                    continue;
                }

                long timestampUs = parseLong(f[0]);
                long jobId = parseLong(f[2]);
                int taskIndex = (int) parseLong(f[3]);
                int eventType = (int) parseLong(f[5]);

                ctx.collect(new TaskEvent(timestampUs, jobId, taskIndex, eventType));
            }
        }
    }

    private static long parseLong(String s) {
        if (s == null || s.isEmpty()) {
            return 0L;
        }
        return Long.parseLong(s);
    }

    @Override
    public void cancel() {
        running = false;
    }
}
"}

