            maxStageCount = getRuntimeContext().getState(new ValueStateDescriptor<>("maxStageCount", Long.class));
            finishTsMs = getRuntimeContext().getState(new ValueStateDescriptor<>("finishTsMs", Long.class));
            emitted = getRuntimeContext().getState(new ValueStateDescriptor<>("emitted", Boolean.class));
        }

        @Override
        public void processElement(Object value, Context ctx, Collector<Tuple2<Long, Long>> out) throws Exception {
            Boolean alreadyEmitted = emitted.value();
            if (alreadyEmitted != null && alreadyEmitted) {
                return;
            }

            if (value instanceof TaskEvent) {
                TaskEvent task = (TaskEvent) value;
                if (task.eventType != TaskEvent.EVENT_SUBMIT) {
                    return;
                }

                long ts = task.timestampMs();

                Long finish = finishTsMs.value();
                if (finish != null && ts > finish) {
                    return;
                }

                Long last = lastSubmitTsMs.value();
                long cur = currentStageCount.value() == null ? 0L : currentStageCount.value();
                long max = maxStageCount.value() == null ? 0L : maxStageCount.value();

                if (last == null) {
                    cur = 1L;
                } else if (ts - last >= sessionGapMs) {
                    max = Math.max(max, cur);
                    cur = 1L;
                } else if (ts >= last) {
                    cur += 1L;
                }

                lastSubmitTsMs.update(ts);
                currentStageCount.update(cur);
                maxStageCount.update(max);
                return;
            }

            if (value instanceof JobEvent) {
                JobEvent job = (JobEvent) value;
                if (job.eventType != JobEvent.EVENT_FINISH) {
                    return;
                }

                long ts = job.timestampMs();
                Long prevFinish = finishTsMs.value();
                if (prevFinish == null || ts < prevFinish) {
                    finishTsMs.update(ts);
                    ctx.timerService().registerEventTimeTimer(ts);
                }
            }
        }

        @Override
        public void onTimer(long timestamp, OnTimerContext ctx, Collector<Tuple2<Long, Long>> out) throws Exception {
            Long finish = finishTsMs.value();
            if (finish == null || finish != timestamp) {
                return;
            }

            Boolean alreadyEmitted = emitted.value();
            if (alreadyEmitted != null && alreadyEmitted) {
                return;
            }

            long cur = currentStageCount.value() == null ? 0L : currentStageCount.value();
            long max = maxStageCount.value() == null ? 0L : maxStageCount.value();
            long result = Math.max(max, cur);

            out.collect(Tuple2.of(ctx.getCurrentKey(), result));

            emitted.update(true);
            lastSubmitTsMs.clear();
            currentStageCount.clear();
            maxStageCount.clear();
            finishTsMs.clear();
        }
    }

    private static final class LocalFileSink extends RichSinkFunction<String> {

        private final String outputPath;
        private transient BufferedWriter writer;

        private LocalFileSink(String outputPath) {
            this.outputPath = outputPath;
        }

        @Override
        public void open(Configuration parameters) throws Exception {
            Path p = Path.of(outputPath);
            Path parent = p.getParent();
            if (parent != null) {
                Files.createDirectories(parent);
            }
            writer = Files.newBufferedWriter(
                    p,
                    StandardCharsets.UTF_8,
                    StandardOpenOption.CREATE,
                    StandardOpenOption.TRUNCATE_EXISTING);
        }

        @Override
        public void invoke(String value, Context context) throws Exception {
            writer.write(value);
            writer.newLine();
        }

        @Override
        public void close() throws IOException {
            if (writer != null) {
                writer.flush();
                writer.close();
            }
        }
    }

    public static void main(String[] args) throws Exception {

        ParameterTool params = ParameterTool.fromArgs(args);
        String taskInput = params.get("task_input", null);
        String jobInput = params.get("job_input", null);
        String outputPath = params.get("output", null);
        System.out.println("task_input  " + taskInput);
        System.out.println("job_input  " + jobInput);
        final int sesssize = params.getInt("sesssize", 600);

        if (taskInput == null || jobInput == null || outputPath == null) {
            throw new IllegalArgumentException("Required parameters: task_input, job_input, output");
        }

        // set up streaming execution environment
        StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();

        WatermarkStrategy<TaskEvent> taskWms = WatermarkStrategy
                .<TaskEvent>forBoundedOutOfOrderness(Duration.ofMinutes(1))
                .withTimestampAssigner((e, ts) -> e.timestampMs());

        WatermarkStrategy<JobEvent> jobWms = WatermarkStrategy
                .<JobEvent>forBoundedOutOfOrderness(Duration.ofMinutes(1))
                .withTimestampAssigner((e, ts) -> e.timestampMs());

        DataStream<TaskEvent> tasks = env
                .addSource(taskSourceOrTest(new TaskEventSource(taskInput)))
                .assignTimestampsAndWatermarks(taskWms);

        DataStream<JobEvent> jobs = env
                .addSource(jobSourceOrTest(new JobEventSource(jobInput)))
                .assignTimestampsAndWatermarks(jobWms);

        KeyedStream<Object, Long> keyed = tasks
                .map((MapFunction<TaskEvent, Object>) e -> (Object) e)
                .keyBy(o -> ((TaskEvent) o).jobId)
                .union(jobs.map((MapFunction<JobEvent, Object>) e -> (Object) e).keyBy(o -> ((JobEvent) o).jobId).getSideOutput(null));

        // The union above is not valid; connect keyed streams instead.
        KeyedStream<TaskEvent, Long> keyedTasks = tasks.keyBy(e -> e.jobId);
        KeyedStream<JobEvent, Long> keyedJobs = jobs.keyBy(e -> e.jobId);

        DataStream<Tuple2<Long, Long>> result = keyedTasks
                .connect(keyedJobs)
                .process(new MaxStageOnJobFinish(sesssize * 1000L));

        DataStream<String> formatted = result
                .map((MapFunction<Tuple2<Long, Long>, String>) v -> "(" + v.f0 + "," + v.f1 + ")");

        formatted
                .addSink((org.apache.flink.streaming.api.functions.sink.SinkFunction<String>) sinkOrTest(new LocalFileSink(outputPath)))
                .setParallelism(1);

        env.execute("LongestSessionPerJob");
    }

}
